  accueil_h1: "El comercio congoleño, del mostrador a la vitrina",
  accueil_heroTexte: "ELEGANZ es un ecosistema pensado para los comerciantes e independientes de Kinshasa: llevar las cuentas, gestionar una tienda y vender en línea — tres herramientas separadas, una sola plataforma, construida y operada desde la RDC.",
  accueil_choisirOutil: "Elegir mi herramienta",
  accueil_aProposLien: "Acerca de ELEGANZ",
  accueil_h2Outils: "¿Qué herramienta le conviene?",
  accueil_outilsIntro: "No necesita conocer la plataforma de antemano: responda la pregunta que le concierne.",
  accueil_questionComptable: "¿Tiene una actividad, sin tienda ni catálogo?",
  accueil_descComptable: "— ventas y gastos por divisa, deudas y cuentas por cobrar, alquileres, pagos a trabajadores, agenda de vencimientos y resúmenes exportables. Seis meses gratis, luego 1 $ al mes.",
  accueil_ouvrirCarnet: "Abrir mi cuaderno",
  accueil_questionGestion: "¿Tiene una tienda, con caja y stock que gestionar?",
  accueil_descGestion: "— la caja, el stock, las facturas y los pedidos de su tienda, con entrega rastreada y equipo integrado, del mostrador al panel de la noche.",
  accueil_ouvrirCaisse: "Abrir mi caja",
  accueil_questionMarket: "¿Busca comprar o vender en línea?",
  accueil_descMarket: "— la vitrina que reúne a vendedores y compradores congoleños, en todos los sectores: búsqueda, pedido y entrega rastreada, estés donde estés.",
  accueil_parcourirVitrine: "Explorar la vitrina",
  apropos_h1: "Una casa, tres habitaciones",
  apropos_intro: "ELEGANZ es un ecosistema pensado para el comercio congoleño, desde el pequeño vendedor informal hasta la tienda establecida: llevar las cuentas, gestionar una tienda y vender en línea — tres herramientas separadas, una sola plataforma, construida y operada desde Kinshasa. La entrega, por ahora, sigue siendo organizada por cada tienda con sus propios repartidores, bajo su propia responsabilidad.",
  apropos_descComptable: "Un cuaderno de gestión diaria para cualquier actividad — comercio, alquiler, servicios, vehículos — sin tienda ni catálogo que crear. Ventas y gastos por divisa, deudas y cuentas por cobrar con pago parcial, gestión de alquileres, pagos a trabajadores, agenda de vencimientos, gráficos y resúmenes exportables, y un expediente preparatorio para una solicitud de financiamiento. Seis meses gratis, luego 1 $ al mes.",
  apropos_descGestion: "La caja, el stock y las facturas de una tienda, con precio negociado al cobrar, importación/exportación Excel del catálogo, estados de actividad certificados, seguimiento de pedidos y disputas, gestión de equipo, y un modo sin conexión que protege cada venta incluso durante un corte de red.",
  apropos_descMarket: "La vitrina que reúne a vendedores y compradores congoleños en un mismo mercado en línea, en todos los sectores. Búsqueda, ficha de producto, carrito, pedido, seguimiento de entrega y opiniones de clientes, para comprar congoleño sin salir de casa.",
  apropos_h2Engagement: "Lo que no hacemos",
  apropos_texteEngagement: "Ningún documento emitido en ELEGANZ se presenta como una factura fiscal homologada mientras la homologación oficial no esté confirmada: cada tienda elige, caso por caso, entre un documento comercial ordinario y una factura fiscal, nunca uno por el otro. Y ningún pago en línea se presenta hoy como confirmado — el pago de los pedidos se hace a la entrega, en efectivo o mobile money, con total transparencia.",
