  cpt_noteAide: "تُنشأ اليومية ودفتر الأستاذ وميزان المراجعة تلقائيًا من العمليات المسجّلة فعليًا (المبيعات، المصاريف، المشتريات، طلبات السوق المستلمة، الفواتير المسدّدة). حساب النتائج والميزانية تقديرات تُنشأ تلقائيًا من هذه القيود نفسها: لا تحل محل محاسبة يحتفظ بها محترف ولا تشكّل تصريحًا ضريبيًا (لا إقفال للسنة المالية ولا قفل للفترة في هذه المرحلة). لا تُسوّى الذمة «411» (مبيعات السوق) تلقائيًا أبدًا ما دام لم يُنمَّط أي تحويل فعلي للأموال من المنصة.",
  cpt_noteConventionSoldeNegatif: "اتفاقية: رصيد تراكمي سالب على حساب ذي رصيد دائن طبيعي (مبيعات، إيرادات) أمر صحيح — يُظهر حجم الدائن المتراكم، وليس خللًا.",
