  apropos_h1: "Nyumba moja, vyumba vitatu",
  apropos_intro: "ELEGANZ ni mfumo ulioundwa kwa biashara ya Kikongo, kutoka muuzaji mdogo asiye rasmi hadi duka lililowekwa: kutunza hesabu, kusimamia duka na kuuza mtandaoni — vifaa vitatu tofauti, jukwaa moja, lililojengwa na kuendeshwa kutoka Kinshasa. Usafirishaji, kwa sasa, unapangwa na kila duka kwa madereva wake, chini ya jukumu lake.",
  apropos_descComptable: "Kitabu cha usimamizi wa kila siku kwa shughuli yoyote — biashara, ukodishaji, huduma, gari — bila duka au katalogi ya kuunda. Mauzo na matumizi kwa sarafu, madeni na mapokeo kwa malipo ya sehemu, usimamizi wa ukodishaji, malipo ya wafanyakazi, kalenda ya makataa, michoro na muhtasari unaoweza kuhamishwa, na faili la maandalizi kwa ombi la ufadhili. Miezi sita bure, kisha $1 kwa mwezi.",
  apropos_descGestion: "Sanduku, hisa na risiti za duka, na bei inayojadiliwa wakati wa malipo, uhamisho wa Excel wa katalogi, taarifa za shughuli zilizothibitishwa, ufuatiliaji wa maagizo na migogoro, usimamizi wa timu, na hali ya nje ya mtandao inayolinda mauzo yote hata wakati wa kukatika kwa mtandao.",
  apropos_descMarket: "Duka la mtandaoni linalounganisha wauzaji na wanunuzi wa Kikongo katika soko moja la mtandaoni, katika sekta zote. Utafutaji, ukurasa wa bidhaa, kikapu, agizo, ufuatiliaji wa usafirishaji na maoni ya wateja, kununua bidhaa za Kikongo bila kuacha nyumbani.",
