  cpt_journalGeneral: "Jarida kuu",
  cpt_noteAide: "Jarida, kitabu kikuu na muhtasari wa mizani vinatengenezwa kiotomatiki kutoka kwa shughuli zilizorekodiwa kweli (mauzo, gharama, ununuzi, maagizo ya Marketplace yaliyopokelewa, ankara zilizolipwa). Taarifa ya matokeo na mizania ni makadirio yanayotengenezwa kiotomatiki kutoka kwa viingilio hivi: hazibadilishi uhasibu unaosimamiwa na mtaalamu na hazijumuishi tamko la kodi (hakuna kufunga mwaka wa fedha, hakuna kufunga kipindi katika hatua hii). Deni la «411» (mauzo ya Marketplace) halilipwi kiotomatiki kamwe maadamu hakuna uhamishaji halisi wa fedha na jukwaa unaowekwa kielelezo.",
  cpt_noteConventionSoldeNegatif: "Mkataba: salio hasi lililokusanywa kwenye akaunti yenye salio la kawaida la krediti (mauzo, mapato) ni sahihi — linaonyesha ukubwa wa krediti iliyokusanywa, si hitilafu.",
  cpt_noteConventionTotauxNegatifs: "Mkataba: jumla hasi hapa zinamaanisha hasara iliyokusanywa tangu mwanzo — mizania inasalia sawia (mali = madeni), tu alama ya matokeo inabadilika.",
  cpt_noteDossierValidation: "Kitabu kamili (mpango wa akaunti, jarida, muhtasari wa mizani, mizania na taarifa ya matokeo zilizosanifiwa) kinakusudiwa kwa mhasibu aliyeidhinishwa — kinahusisha, kwa chaguo-msingi, mwaka wa fedha wa sasa hadi tarehe iliyoonyeshwa hapo juu.",
