  accueil_h1: "Mombongo ya Kongo, banda na magazini tii na site ya kotekisa na internet",
  accueil_heroTexte: "ELEGANZ ezali ebongiseli esalemi mpo na bato ya mombongo mpe bato bamesana na Kinshasa: kobatela mbongo, kotambwisa magazini mpe koteka na internet — bisaleli misato ekeseni, plateforme moko, etongami mpe esalemi na RDC.",
  accueil_choisirOutil: "Pona esaleli na ngai",
  accueil_aProposLien: "Na ntina na ELEGANZ",
  accueil_h2Outils: "Esaleli nini ekoki na yo?",
  accueil_outilsIntro: "Esengeli te koyeba plateforme liboso : yanola motuna oyo etali yo.",
  accueil_questionComptable: "Osalaka mosala, kasi ozali na magazini te to catalogue te?",
  accueil_descComptable: "— koteka mpe kobimisa mbongo na mbongo ya ekolo, nyongo mpe baye bazali na nyongo epai na yo, mbongo ya ndako, lifuta ya basali, kalandriye ya mikolo ya kofuta mpe mikanda oyo ekoki kozwama. Sanza motoba ya ofele, na sima dolare 1 na sanza.",
  accueil_ouvrirCarnet: "Fungola buku na ngai",
  accueil_questionGestion: "Ozali na magazini, na caisse mpe biloko ya kotambwisa?",
  accueil_descGestion: "— caisse, biloko, fature mpe commande ya magazini na yo, elongo na kokamba oyo bakolandaka mpe ekipi ya kati, banda na magazini tii na tableau ya mpokwa.",
  accueil_ouvrirCaisse: "Fungola caisse na ngai",
  accueil_questionMarket: "Olingi kosomba to koteka na internet?",
  accueil_descMarket: "— esika oyo eyangani batekisi mpe basombi ya Kongo, na mabongisi nyonso : koluka, commande mpe kokamba oyo bakolandaka, esika nyonso ozali.",
  accueil_parcourirVitrine: "Tala esika ya koteka",
  apropos_h1: "Ndako moko, bashambre misato",
  apropos_intro: "ELEGANZ ezali ebongiseli esalemi mpo na mombongo ya Kongo, banda na moto oyo atekaka na mabele tii na magazini ya solo : kobatela mbongo, kotambwisa magazini mpe koteka na internet — bisaleli misato ekeseni, plateforme moko, etongami mpe esalemi na Kinshasa. Kokamba, yango, ezali kaka kobongisama na magazini moko na moko na ba-sofeur na yango, na se ya mokumba na yango moko.",
  apropos_descComptable: "Buku ya kotambwisa mokolo na mokolo mpo na mosala nyonso — mombongo, kofutisa ndako, mosala, motuka — kozanga magazini to catalogue ya kosala. Koteka mpe kobimisa mbongo na mbongo ya ekolo, nyongo na baye bazali na nyongo na kofuta ndambo, kotambwisa kofutisa ndako, lifuta ya basali, kalandriye ya mikolo ya kofuta, bililingi mpe mikanda oyo ekoki kozwama, mpe dosye ya kobongisa mpo na kosenga mbongo. Sanza motoba ya ofele, na sima dolare 1 na sanza.",
  apropos_descGestion: "Caisse, biloko mpe fature ya magazini, na motuya oyo bayokani na ntango ya kofuta, kokotisa/kobimisa catalogue na Excel, balapolo ya mosala oyo endimami, kolanda ba commande mpe matata, kotambwisa ekipi, mpe mozindo ya kozanga internet oyo ebatelaka koteka nyonso ata soki réseau ekati.",
  apropos_descMarket: "Esika oyo eyangani batekisi mpe basombi ya Kongo na zando moko ya internet, na mabongisi nyonso. Koluka, lokasa ya eloko, panye, commande, kolanda kokamba mpe makanisi ya ba client, mpo na kosomba biloko ya Kongo kozanga kobima na ndako.",
  apropos_h2Engagement: "Oyo tosalaka te",
  apropos_texteEngagement: "Mokanda moko te oyo ebimisami na ELEGANZ emonisami lokola fature ya mpako endimami soki homologation ya leta eyebani naino te : magazini moko na moko eponaka, kolanda ebongiseli, kati na mokanda ya mombongo ya momeseno mpe fature ya mpako, kasi moko mpo na mosusu te. Mpe lifuta moko te ya internet emonisami lelo lokola eyebani — lifuta ya commande esalemaka na ntango ya kokamba, na mbongo ya mabele to mobile money, na bosembo nyonso.",
  footer_tagline_accueil: "Ndako moko, bashambre ebele : magazini, esika ya koteka mpe nzela.",
  footer_tagline_gestion: "Caisse mpe magazini, ebongisami malamu.",
