  cpt_noteAide: "Journal, buku monene mpe balance esalemi na mayele na mayele ut na misala esalemaki mpenza (koteka, charges, kosomba, ba commande ya Marketplace eyamaki, ba facture efutami). Compte ya résultat mpe bilan ezali estimation esalemi na mayele na mayele ut na ba écritures wana : ezali te esika ya comptabilité oyo mohasibu asalaka, mpe ezali te déclaration ya mpako (kokanga exercice te, kokanga période te na ntango oyo). Nyongo « 411 » (koteka ya Marketplace) efutami te na mayele na mayele soki kozongisa mbongo ya solo na plateforme ekomami nanu te.",
