  apropos_descComptable: "Kahya ya kutwadisa lumbu na lumbu sambu na kisalu yoso — mvwandu, kufutisa nzo, kisalu, motuka — kaka ve na zandu to catalogue ya kusala. Mteka ye mbongo ya kubimisa na zimbongo, maniongo ye bina bekubikudila na kufuta fioti, kutwadisa kufutisa nzo, nsendo ya basadi, kalandari ya bilumbu ya kufuta, bifwani ye mabakulu ma kubongisa, ye dossier ya ntete sambu na lomba mbongo. Ngonda nsambwadi ya mfwenina, na nima dola 1 na ngonda.",
