  cpt_journalGeneral: "Journal munene",
  cpt_noteAide: "Journal, mukanda munene ne balance bidi bienzeka ku mushindu wa kal'utuadi ku midimu idi yenzeka bulelela (diteka, charges, kusumba, ba commande wa Marketplace idi yatambula, ba facture idi yafuta). Compte wa résultat ne bilan bidi ba estimation bienzeka ku mushindu wa kal'utuadi ku ba écritures abe : kabiena mifubo ya mohasibu, kabiena pawa déclaration wa mpako (kukangela exercice to, kukangela période to mu tshikondo etshi). Nyongo « 411 » (diteka dia Marketplace) kaufuti ku mushindu wa kal'utuadi too ne mudimu wa kieleka wa kuvuija mali ku plateforme autelama katshia.",
  cpt_noteConventionSoldeNegatif: "Lungenyi : solde wa minus pa compte udi ne solde wa crédit wa bushuwa (diteka, mapindieu) mmuoyo — udi uleja bunene bua crédit budi buvuangana, kena mpata to.",
  cpt_noteConventionTotauxNegatifs: "Lungenyi : miela ya minus eu idi yumvuija dipanga didi divuangana ku mutuadijilu — bilan udi ushala ne balance (bintu = minyongo), anu dimanyinu dia résultat didi dishintuluka.",
  cpt_noteDossierValidation: "Mukanda mujima (plan wa ba comptes, journal, balance, bilan ne compte wa résultat wa normalisé) wenzela mohasibu wukadi mulombolwe — ukumbaja, mu mushindu wa kutuadija, exercice wa mpindieu too ne ku dituku didi dimueneka ku dilu.",
